components.css:
.ds-wordmark {display: inline-flex;
  min-height: 44px;
  align-items: center;
  font-family: var(--font-heading), sans-serif;
  font-size: 34px;
  font-weight: 800;
  letter-spacing: -0.03em;}
.ds-wordmark span {color: var(--color-sorbus-700);}
.ds-wordmark:focus-visible {outline: 2px solid var(--color-sorbus-700);
  outline-offset: 4px;}
:host-context(.dark) .ds-wordmark span {color: var(--color-sorbus-300);}
.ds-wordmark {color:var(--color-page-fg);text-decoration:none;}
:host-context(.dark) .ds-wordmark {color:var(--color-whitedarktheme);}

.ds-theme-button {min-width: 44px;
  min-height: 44px;
  align-items: center;
  justify-content: center;
  border-radius: 12px;}
button.ds-theme-button {display: inline-flex;}
.ds-theme-button:hover {background: #ededee;}
.ds-theme-button:focus-visible {outline: 2px solid var(--color-sorbus-700);
  outline-offset: 4px;}
:host-context(.dark) .ds-theme-button:hover {background: #2a2e35;}
.ds-theme-button {font-family:var(--font-heading),ui-sans-serif,system-ui,sans-serif;background:transparent;color:var(--color-page-fg);border:none;}
:host-context(.dark) .ds-theme-button {color:var(--color-whitedarktheme);}

.ds-topic-filter {min-inline-size: 0; max-inline-size: 100%; display: flex; gap: 8px; overflow-x: auto; padding: 10px 0 16px; scrollbar-width: thin; scrollbar-color: #d1d5db transparent;}
.ds-topic-filter button {flex: none; min-height: 44px; padding: 8px 16px; border-radius: 999px; background: #eeeeef; color: #535963; font-size: 13px; font-weight: 600; cursor: pointer;}
.ds-topic-filter button[aria-pressed="true"] {background: #202124; color: #fafafa;}
.ds-topic-filter button:hover {background: #e1e2e5; color: #202124;}
.ds-topic-filter button[aria-pressed="true"]:hover {background: #343942; color: #fafafa;}
.ds-topic-filter button:focus-visible {outline: 2px solid var(--color-sorbus-700);
  outline-offset: 4px;}
:host-context(.dark) .ds-topic-filter button {background: #292d34; color: #bcc2cd;}
:host-context(.dark) .ds-topic-filter button[aria-pressed="true"] {background: #e0e0e0; color: #181a1e;}
:host-context(.dark) .ds-topic-filter button:hover {background: #383e48; color: #fafafa;}
:host-context(.dark) .ds-topic-filter button[aria-pressed="true"]:hover {background: #ffffff; color: #181a1e;}
.ds-topic-filter button {font-family:var(--font-heading),ui-sans-serif,system-ui,sans-serif;border:none;}

.ds-topic-filter {min-inline-size: 0; max-inline-size: 100%; display: flex; gap: 8px; overflow-x: auto; padding: 10px 0 16px; scrollbar-width: thin; scrollbar-color: #d1d5db transparent;}
