.ds-mobile-tab {min-height: 52px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border-radius: 12px;
  color: #555b65;
  font-size: 11px;
  font-weight: 600;}
.ds-mobile-tab[aria-current] {color: var(--color-sorbus-700); background: var(--color-sorbus-50);}
.ds-mobile-tab:focus-visible {outline: 2px solid var(--color-sorbus-700);
  outline-offset: 4px;}
:host-context(.dark) .ds-mobile-tab {color: #a7adb8;}
:host-context(.dark) .ds-mobile-tab[aria-current] {color: var(--color-sorbus-300); background: #2d231e;}
.ds-mobile-tab {font-family:var(--font-heading),ui-sans-serif,system-ui,sans-serif;text-decoration:none;}

.ds-topic-index-link {min-height: 76px; display: flex; align-items: center; justify-content: space-between; gap: 12px; border-bottom: 1px solid #dfe1e5; font-size: 16px; font-weight: 600;}
.ds-topic-index-link span:first-child {overflow-wrap: anywhere;}
.ds-topic-index-link span:last-child {color: #606671; font-size: 13px; font-weight: 500; font-variant-numeric: tabular-nums;}
.ds-topic-index-link:hover {color: var(--color-sorbus-700);}
.ds-topic-index-link:focus-visible {outline: 2px solid var(--color-sorbus-700);
  outline-offset: 4px;}
:host-context(.dark) .ds-topic-index-link span:last-child {color: #a7adb8;}
:host-context(.dark) .ds-topic-index-link {border-color: #32363d;}
:host-context(.dark) .ds-topic-index-link:hover {color: var(--color-sorbus-300);}
.ds-topic-index-link {font-family:var(--font-heading),ui-sans-serif,system-ui,sans-serif;color:var(--color-page-fg);text-decoration:none;}
:host-context(.dark) .ds-topic-index-link {color:var(--color-whitedarktheme);}
:host-context(.dark) .ds-topic-index-link:hover {color:var(--color-sorbus-300);}
